import{_ as o,a0 as r,w as c,s as g,ao as n,I as a,x as e,a1 as i,A as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const f=JSON.parse('{"title":"如何將 Oracle 11g 升級到 Orcale 12c | LCTT x X-CMD","titleTemplate":false,"description":"如何將 Oracle 11g 升級到 Orcale 12c | LCTT (201510) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何將 Oracle 11g 升級到 Orcale 12c | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何將 Oracle 11g 升級到 Orcale 12c | LCTT (201510) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201510/20150923 How To Upgrade From Oracle 11g To Oracle 12c","title":"如何將 Oracle 11g 升級到 Orcale 12c","tag":"201510","desc":""},"relativePath":"201510/20150923 How To Upgrade From Oracle 11g To Oracle 12c.md","filePath":"[post].md"}'),s={name:"201510/20150923 How To Upgrade From Oracle 11g To Oracle 12c.md"};function m(w,l,d,u,x,b){const t=r("Link");return c(),g("div",null,[l[20]||(l[20]=n('<h1 id="如何將-oracle-11g-升級到-orcale-12c" tabindex="-1">如何將 Oracle 11g 升級到 Orcale 12c <a class="header-anchor" href="#如何將-oracle-11g-升級到-orcale-12c" aria-label="Permalink to “如何將 Oracle 11g 升級到 Orcale 12c”">​</a></h1><p>大家好。今天我們來學習一下如何將 Oracle 11g 升級到 Oracle 12c。開始吧。</p><p>在此，我使用的是 CentOS 7 64 位 Linux 發行版。我假設你已經在你的系統上安裝了 Oracle 11g。這裏我會展示一下安裝 Oracle 11g 時我的操作步驟。</p><p>我在 Oracle 11g 上選擇 “Create and configure a database”，如下圖所示。</p><p><img src="http://www.unixmen.com/wp-content/uploads/2015/09/11g212cimage1.png" alt=""></p><p>然後我選擇安裝 Oracle 11g “Decktop Class”。如果是生產環境，你必須選擇 “Server Class”。</p><p><img src="http://www.unixmen.com/wp-content/uploads/2015/09/11g212cimage2.png" alt=""></p><p>然後你輸入安裝 Oracle 11g 的各種路徑以及密碼。下面是我自己的 Oracle 11g 安裝配置。確保你正確輸入了 Oracle 的密碼。</p><p><img src="http://www.unixmen.com/wp-content/uploads/2015/09/11g212cimage3.png" alt=""></p><p>下一步，我按照如下設置 Inventory Directory。</p><p><img src="http://www.unixmen.com/wp-content/uploads/2015/09/11g212cimage4.png" alt=""></p><p>到這裏，我已經向你展示了我安裝 Oracle 11g 所做的工作，因為我們開始想升級到 12c。</p><p>讓我們將 Oracle 11g 升級到 Oracle 12c 吧。</p>',13)),a("p",null,[l[1]||(l[1]=e("你需要從該",-1)),i(t,{href:"http://www.oracle.com/technetwork/database/enterprise-edition/downloads/database12c-linux-download-1959253.html"},{default:p(()=>[...l[0]||(l[0]=[e("鏈接",-1)])]),_:1}),l[2]||(l[2]=e("上下載兩個 zip 文件。下載並解壓兩個文件到相同目錄。文件名為 ",-1)),l[3]||(l[3]=a("strong",null,"linuxamd64_12c_database_1of2.zip",-1)),l[4]||(l[4]=e(" & ",-1)),l[5]||(l[5]=a("strong",null,"linuxamd64_12c_database_2of2.zip",-1)),l[6]||(l[6]=e("。提取或解壓完後，它會創建一個名為 database 的文件夾。",-1))]),l[21]||(l[21]=n(`<p>注意：升級到 12c 之前，請確保在你的 CentOS 上已經安裝了所有必須的軟件包，並且所有的路徑變量也已經正確配置，還有其它前提條件也已經滿足。</p><p>下面是必須使用正確版本安裝的一些軟件包</p><ul><li>binutils</li><li>compat-libstdc++</li><li>gcc</li><li>glibc</li><li>libaio</li><li>libgcc</li><li>libstdc++</li><li>make</li><li>sysstat</li><li>unixodbc</li></ul><p>在因特網上搜索正確的 rpm 版本。</p><p>你也可以用一個查詢處理多個軟件包，然後在輸出中查找正確版本。例如，在終端中輸入下面的命令：</p><pre><code>rpm -q binutils compat-libstdc++ gcc glibc libaio libgcc libstdc++ make sysstat unixodbc
</code></pre><p>你的系統中必須安裝了以下軟件包（版本可能或新或舊）</p><ul><li>binutils-2.23.52.0.1-12.el7.x86_64</li><li>compat-libcap1-1.10-3.el7.x86_64</li><li>gcc-4.8.2-3.el7.x86_64</li><li>gcc-c++-4.8.2-3.el7.x86_64</li><li>glibc-2.17-36.el7.i686</li><li>glibc-2.17-36.el7.x86_64</li><li>glibc-devel-2.17-36.el7.i686</li><li>glibc-devel-2.17-36.el7.x86_64</li><li>ksh</li><li>libaio-0.3.109-9.el7.i686</li><li>libaio-0.3.109-9.el7.x86_64</li><li>libaio-devel-0.3.109-9.el7.i686</li><li>libaio-devel-0.3.109-9.el7.x86_64</li><li>libgcc-4.8.2-3.el7.i686</li><li>libgcc-4.8.2-3.el7.x86_64</li><li>libstdc++-4.8.2-3.el7.i686</li><li>libstdc++-4.8.2-3.el7.x86_64</li><li>libstdc++-devel-4.8.2-3.el7.i686</li><li>libstdc++-devel-4.8.2-3.el7.x86_64</li><li>libXi-1.7.2-1.el7.i686</li><li>libXi-1.7.2-1.el7.x86_64</li><li>libXtst-1.2.2-1.el7.i686</li><li>libXtst-1.2.2-1.el7.x86_64</li><li>make-3.82-19.el7.x86_64</li><li>sysstat-10.1.5-1.el7.x86_64</li></ul><p>你也需要 unixODBC-2.3.1 或更新版本的驅動。</p><p>我希望你安裝 Oracle 11g 的時候已經在你的 CentOS 7 上創建了名為 oracle 的用户。讓我們以用户 oracle 登錄 CentOS。以用户 oracle 登錄到 CentOS 之後，在你的 CentOS上打開一個終端。</p><p>使用終端更改工作目錄並導航到你解壓兩個 zip 文件的目錄。在終端中輸入以下命令開始安裝 12c。</p><pre><code>./runInstaller
</code></pre><p><img src="http://www.unixmen.com/wp-content/uploads/2015/09/11g212image5.png" alt=""></p><p>如果一切順利，你會看到類似下面的截圖，已經開始安裝 12c。</p><p><img src="http://www.unixmen.com/wp-content/uploads/2015/09/11g212cimage6.png" alt=""></p><p>然後你可以選擇跳過更新或者下載最近更新。如果是生產服務器，建議你必須更新。我這裏選擇跳過。</p><p><img src="http://www.unixmen.com/wp-content/uploads/2015/09/11g212cimage7.png" alt=""></p><p>現在，選擇升級現有資料庫。</p><p><img src="http://www.unixmen.com/wp-content/uploads/2015/09/11g212cimage8.png" alt=""></p><p>對於語言，這裏已經有 English。點擊下一步繼續，或者你可以根據你的需要添加語言。</p><p><img src="http://www.unixmen.com/wp-content/uploads/2015/09/11g212cimage9.png" alt=""></p><p>現在，選擇企業版。你可以根據你的需求選擇。</p><p><img src="http://www.unixmen.com/wp-content/uploads/2015/09/11g212cimage10.png" alt=""></p><p>然後選擇軟件位置路徑，這些都是不言自明的。</p><p><img src="http://www.unixmen.com/wp-content/uploads/2015/09/11g212cimage11.png" alt=""></p><p>對於第七步，像下面這樣使用默認的選擇繼續下一步。</p><p><img src="http://www.unixmen.com/wp-content/uploads/2015/09/11g212cimage12.png" alt=""></p><p>在第九步中，你會看到一個類似下面這樣的總結報告。</p><p><img src="http://www.unixmen.com/wp-content/uploads/2015/09/11g212cimage13.png" alt=""></p><p>如果一切正常，你可以點擊第九步中的 install 開始安裝，進入第十步。</p><p><img src="http://www.unixmen.com/wp-content/uploads/2015/09/11g212cimage14.png" alt=""></p><p>其中你可能會遇到一些錯誤，你需要通過谷歌找到這些錯誤的解決方法。你可能遇到的問題會有很多，因此我沒有在這裏詳細介紹。</p><p>要有耐心，一步一步走下來最後它會告訴你成功了。否則，在谷歌上搜索做必要的操作解決問題。再一次説明，由於你可能會遇到的錯誤有很多，我無法在這裏提供所有詳細介紹。</p><p>現在，只需要按照下面屏幕指令配置監聽器。</p><p>配置完監聽器之後，它會啓動資料庫升級助手（Database Upgrade Assistant）。選擇 Upgrade Oracle Database。</p><p><img src="http://www.unixmen.com/wp-content/uploads/2015/09/DUAimage15.png" alt=""></p><p>在第二步，你會發現它顯示了 11g 的位置路徑以及 12c 的位置路徑。同時你也會發現它指示説從原來的 Oracle Home Release 11 安裝 Oracle Home Release 12.點擊下一步進入步驟三。</p><p><img src="http://www.unixmen.com/wp-content/uploads/2015/09/DUAimage16.png" alt=""></p><p>按照屏幕上的説明完成安裝。</p><p>在最後一步，你會看到一個成功窗口，其中你會看到成功升級了 oracle 資料庫。</p><p><strong>一個忠告</strong>：對於你的生產服務器，在升級到 12c 之前，請確保你已經在其它平台上測試過，以便你能修復升級過程中遇到的所有錯誤。永遠不要嘗試一無所知的時候就升級生產服務器。</p><hr>`,42)),a("p",null,[l[8]||(l[8]=e("via: ",-1)),i(t,{href:"http://www.unixmen.com/upgrade-from-oracle-11g-to-oracle-12c/"},{default:p(()=>[...l[7]||(l[7]=[e("http://www.unixmen.com/upgrade-from-oracle-11g-to-oracle-12c/",-1)])]),_:1})]),a("p",null,[l[12]||(l[12]=e("作者：",-1)),i(t,{href:"http://www.unixmen.com/author/forhad/"},{default:p(()=>[...l[9]||(l[9]=[e("Mohammad Forhad Iftekher",-1)])]),_:1}),l[13]||(l[13]=e(" 譯者：",-1)),i(t,{href:"http://www.mutouxiaogui.cn/blog/"},{default:p(()=>[...l[10]||(l[10]=[e("ictlyh",-1)])]),_:1}),l[14]||(l[14]=e(" 校對：",-1)),i(t,{href:"https://github.com/wxy"},{default:p(()=>[...l[11]||(l[11]=[e("wxy",-1)])]),_:1})]),a("p",null,[l[17]||(l[17]=e("本文由 ",-1)),i(t,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...l[15]||(l[15]=[e("LCTT",-1)])]),_:1}),l[18]||(l[18]=e(" 原創編譯，",-1)),i(t,{href:"https://linux.cn/"},{default:p(()=>[...l[16]||(l[16]=[e("Linux中國",-1)])]),_:1}),l[19]||(l[19]=e(" 榮譽推出",-1))])])}const _=o(s,[["render",m]]);export{f as __pageData,_ as default};
